select saa.id as appSystemId, saa.`name` as appSystemName, saa.`abbr_name` as appSystemNameAbbrName, saa.app_module_id as appModuleId, saa.`app_module_name` as appModuleName, saa.`app_module_abbr_name` as appModuleNameAbbrName, if(dacu.user_uuid is null,0,1) as isFavorite, if(dac.config is null,0,1) as isConfig, if( daca.app_system_id IS NULL, 0, 1 ) AS isConfigAuthority, daca.auth_type as authType, daca.auth_uuid as authUuid, daca.`action` as authAction, daca.action_type authActionType from @{DATA_SCHEMA}.`scence_appsystem_appmodule` saa left join deploy_app_config_user dacu on saa.id = dacu.app_system_id and dacu.user_uuid = #{userUuid} left join deploy_app_config dac on saa.id = dac.app_system_id and dac.app_module_id = 0 and dac.env_id = 0 LEFT JOIN deploy_app_config_authority daca ON daca.app_system_id = saa.id
AND daca.auth_uuid IN ( 'alluser'
,
#{item}
)
saa.id in
#{id}
order by if(dacu.user_uuid = #{userUuid},1,0) desc, CONVERT(saa.abbr_name USING gbk) COLLATE gbk_chinese_ci ASC, CONVERT(saa.app_module_abbr_name USING gbk) COLLATE gbk_chinese_ci ASC

