LEFT JOIN deploy_app_config_authority daca ON daca.app_system_id = a.id
left join deploy_app_config dac on a.`id` = dac.app_system_id and dac.app_module_id = 0 and dac.env_id = 0
1=1
and ( a.`name` LIKE concat('%', #{searchVo.keyword}, '%') or a.`app_module_name` LIKE concat('%',#{searchVo.keyword}, '%') or a.`abbr_name` LIKE concat('%', #{searchVo.keyword}, '%')or a.`app_module_abbr_name` LIKE concat('%',#{searchVo.keyword}, '%'))
AND a.`id` IN
#{item}
